 (d/'prompt.txt').write_text(prompt,'utf8');write(d/'input.json',{'refs':[95,97],'forms_by_column':['base','fourth'],'parent':{'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p.read_bytes())},'source_layout':{'size':[1536,1536],'grid':[2,2],'native_cell':[96,96],'native_origin':[48,48],'crop':list(crop),'scale':.125},'rows':rows,'policy':'현재 수용 포즈를 유지하는 새 상세 그림이며 원작 전체 복원으로 주장하지 않는다.','original_game_art_sent':False,'files':{q.name:sha(q.read_bytes())for q in d.iterdir()if q.is_file()}});print(d)
